"use client";
import { useEffect, useState } from "react";
import { defaultContent, type PackageItem, type SiteContent } from "../../../lib/site-types";
export default function PackagePage({params}:{params:Promise<{id:string}>}){const [item,setItem]=useState<PackageItem|null>(null);useEffect(()=>{params.then(({id})=>fetch("/api/content").then(r=>r.json()).then((data:SiteContent)=>setItem(data.packages[Number(id)]||null)));},[params]);if(!item)return <main className="orderPage"><p>پکیج پیدا نشد.</p></main>;return <main className="orderPage" dir="rtl"><a className="back" href="/#packages">← بازگشت به پکیج‌ها</a><section className="orderBox packagePage"><img src={item.image||defaultContent.packageImage} alt={item.name}/><div><small>{item.age}</small><h1>{item.name}</h1><p>{item.details||item.description}</p><h3>{item.price||"استعلام قیمت"}</h3><h2>محتویات پکیج</h2><p>{item.includes||"اطلاعات این بخش از پنل مدیریت تکمیل می‌شود."}</p><a className="button" href={`/order?package=${encodeURIComponent(item.name)}`}>ثبت درخواست این پکیج</a></div></section></main>}
